import json
from pathlib import Path

FILE = Path("expenses.json")

def load_expenses():
    if not FILE.exists():
        return []
    try:
        return json.loads(FILE.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return []

def save_expenses(expenses):
    FILE.write_text(json.dumps(expenses, indent=2), encoding="utf-8")

def show(expenses):
    if not expenses:
        print("No expenses yet.")
        return
    total = sum(item["amount"] for item in expenses)
    for i, item in enumerate(expenses, 1):
        print(f"{i}. {item['category']}: ${item['amount']:.2f} - {item['note']}")
    print(f"Total: ${total:.2f}")

def main():
    expenses = load_expenses()
    while True:
        print("\n1) Add  2) List  3) Delete  4) Quit")
        choice = input("Choose: ").strip()
        if choice == "1":
            try:
                amount = float(input("Amount: "))
                if amount < 0: raise ValueError
            except ValueError:
                print("Enter a non-negative number.")
                continue
            category = input("Category: ").strip() or "Other"
            note = input("Note: ").strip()
            expenses.append({"amount": amount, "category": category, "note": note})
            save_expenses(expenses)
        elif choice == "2":
            show(expenses)
        elif choice == "3":
            show(expenses)
            try:
                index = int(input("Number to delete: ")) - 1
                removed = expenses.pop(index)
                save_expenses(expenses)
                print(f"Deleted {removed['note'] or removed['category']}.")
            except (ValueError, IndexError):
                print("Invalid expense number.")
        elif choice == "4":
            break
        else:
            print("Choose 1, 2, 3, or 4.")

main()

