import logging

DATA_FILE = Path("work_items.json")
logging.basicConfig(level=logging.INFO, format="%(levelname)s: %(message)s")

@dataclass
class WorkItem:
    title: str
    priority: str = "normal"
    done: bool = False

def load_items():
    if not DATA_FILE.exists():
        return []
    try:
        raw = json.loads(DATA_FILE.read_text(encoding="utf-8"))
        return [WorkItem(**item) for item in raw]
    except (OSError, json.JSONDecodeError, TypeError):
        logging.exception("Could not load saved data")
        return []

def save_items(items):
    DATA_FILE.write_text(json.dumps([item.__dict__ for item in items], indent=2), encoding="utf-8")

def list_items(items):
    if not items:
        print("No work items yet.")
        return
    for i, item in enumerate(items, 1):
        mark = "x" if item.done else " "
        print(f"{i}. [{mark}] {item.title} ({item.priority})")

def main():
    items = load_items()
    while True:
        print("\n=== Work Tracker ===")
        print("1) Add  2) List  3) Complete  4) Save  5) Quit")
        choice = input("Choose: ").strip()
        if choice == "1":
            title = input("Title: ").strip()
            priority = input("Priority (low/normal/high): ").strip().lower() or "normal"
            if title and priority in {"low", "normal", "high"}:
                items.append(WorkItem(title, priority))
            else:
                print("Use a title and a valid priority.")
        elif choice == "2":
            list_items(items)
        elif choice == "3":
            try:
                index = int(input("Item number: ")) - 1
                items[index].done = True
            except (ValueError, IndexError):
                print("Invalid item number.")
        elif choice == "4":
            save_items(items)
            logging.info("Saved %d items", len(items))
        elif choice == "5":
            save_items(items)
            print("Saved. Goodbye!")
            break
        else:
            print("Choose a number from 1 to 5.")

main()
